    <header>
        <div class="container">
            <h1>Global Intentional Homicide Trends</h1>
            <div class="subtitle">A Multi-Dimensional Analysis (1990–2023)</div>
        </div>
    </header>

    <div class="container">
        <!-- Executive KPI Dashboard -->
        <div class="kpi-dashboard">
            <div class="kpi-card">
                <div class="kpi-label">Global Median Homicide Rate (2023)</div>
                <div class="kpi-value">1.84</div>
